const addExpense = (list, item, amount, category) => [...list, { item, amount, category }]
const total = (list) => list.reduce((sum, e) => sum + e.amount, 0)
const byCategory = (list) => list.reduce((acc, e) => {
  acc[e.category] = (acc[e.category] ?? 0) + e.amount
  return acc
}, {})
const biggest = (list) => list.length ? list.reduce((a, b) => (b.amount > a.amount ? b : a)) : null
function save(key, list, storage = localStorage) {
  storage.setItem(key, JSON.stringify(list))
}
function load(key, storage = localStorage) {
  return JSON.parse(storage.getItem(key) ?? "[]")
}
